package contabancaria.poo.exercise.domain;public class ContaBancaria {    private String titular;    private double saldo;    private int numeroDaConta;    public void setTitular ( String titular ) {    if ( this.titular == "" || this.titular == null ) {        System.out.println("Titular inválido");    } else        this.titular = titular;    }    public void setSaldo ( double saldo ) {        if ( this.saldo <= 0 )            System.out.println("Erro, saldo negativo ou nulo!");         else            this.saldo = saldo;    }    public void setNumeroDaConta ( int numeroDaConta ) {        this.numeroDaConta = numeroDaConta;    }    public void depositar ( double deposito ) {        this.saldo += deposito;    }    public void saque ( double saque ) {        if ( this.saldo <= 0 )            System.out.println("Impossivel fazer o saque, saldo insuficiente!");        else            this.saldo -= saque;    }    public void transferir ( double transferir ) {        if ( this.saldo <= 0 )            System.out.println("Não foi possível fazer a transferência");        else            this.saldo -= transferir;    }    public void mostarDados () {        System.out.println(this.titular);        System.out.println(this.saldo);        System.out.println(this.numeroDaConta);    }}